void WallpaperHostAsyncWaiter::GetWallpaper(
    std::vector<uint8_t>* out_wallpaper) {
  base::RunLoop loop;
  proxy_->GetWallpaper(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<uint8_t>* out_wallpaper
,
             const std::vector<uint8_t>& wallpaper) {*out_wallpaper = std::move(wallpaper);
            loop->Quit();
          },
          &loop,
          out_wallpaper));
  loop.Run();
}

std::vector<uint8_t> WallpaperHostAsyncWaiter::GetWallpaper(
    ) {
  std::vector<uint8_t> async_wait_result;
  GetWallpaper(&async_wait_result);
  return async_wait_result;
}




